const s = $input.first();
let handle = (s.json['Instagram_Handle'] || '').replace(/^@/, '').trim();
if (!handle) {
  const url = (s.json['Instagram_Links'] || s.json['Links'] || '');
  const match = url.match(/instagram\.com\/([^/?#]+)/);
  if (match && !['p','reel','tv','explore','stories'].includes(match[1])) handle = match[1].trim();
}
const source_id = s.json.id || '';
const source_name = s.json['Source Name'] || '';
if (!handle) {
  console.log('[2a] No handle found for: ' + source_name + ', will mark backfilled and skip');
  return [{ json: { _skip: true, source_id, source_name } }];
}
const profileUrl = 'https://www.instagram.com/' + handle + '/';
const sourceMap = {};
sourceMap[handle.toLowerCase()] = { source_id, source_name, handle: '@' + handle };
console.log('[2a] Processing source: ' + source_name + ' (' + profileUrl + ')');
return [{ json: { directUrls: [profileUrl], source_map: sourceMap, source_id, source_name } }];

const apifyInput = $('2a. Prepare Single Source Input').first().json;
const sourceMap = apifyInput.source_map || {};
const source_id = apifyInput.source_id;
const source_name = apifyInput.source_name;

const currentYear = new Date().getFullYear();
const currentYearStart = currentYear + '-01-01';

const allPosts = $input.all().map(i => i.json).filter(v => v && typeof v === 'object' && !v.error);
console.log('[4] Apify returned ' + allPosts.length + ' total posts for: ' + source_name);

if (!allPosts.length) {
  return [{ json: { _skip_videos: true, source_id, source_name } }];
}

const results = [];
for (const post of allPosts) {
  const postType = (post.type || post.productType || post.__typename || '').toUpperCase();
  if (postType === 'IMAGE' || postType === 'CAROUSEL_ALBUM' || postType === 'SIDECAR') continue;
  const hasVideoSignal = post.videoPlayCount != null || post.videoViewCount != null || post.playsCount != null || post.videoDuration != null || post.isVideo === true;
  if (!hasVideoSignal && (postType === 'IMAGE' || postType === '')) continue;

  // Filter to current year only
  const publishedAt = post.timestamp || post.takenAtTimestamp || '';
  if (publishedAt) {
    const postDate = typeof publishedAt === 'number'
      ? new Date(publishedAt * 1000).toISOString()
      : String(publishedAt);
    if (postDate < currentYearStart) {
      console.log('[4] Pre-' + currentYear + ' skip: ' + postDate);
      continue;
    }
  }

  const username = (post.ownerUsername || post.username || '').toLowerCase().trim();
  const sourceInfo = sourceMap[username] || { source_id, source_name, handle: '@' + username };
  const postId = String(post.id || post.shortCode || '');
  if (!postId) continue;

  const parseNum = (val) => {
    if (val == null) return 0;
    const s = String(val).replace(/,/g, '').trim();
    if (s.endsWith('M')) return Math.round(parseFloat(s) * 1000000);
    if (s.endsWith('K')) return Math.round(parseFloat(s) * 1000);
    return parseInt(s) || 0;
  };

  const viewCount = parseNum(post.videoPlayCount || post.videoViewCount || post.playsCount || 0);
  const likeCount = parseNum(post.likesCount || post.likes || 0);
  const commentCount = parseNum(post.commentsCount || post.comments || 0);
  const duration = parseInt(post.videoDuration || post.duration || 0);
  const caption = post.caption || post.text || post.description || '';
  const shortCode = post.shortCode || post.id || '';
  const url = post.url || ('https://www.instagram.com/reel/' + shortCode + '/');
  let tags = '';
  const hashtagMatches = caption.match(/#[\w\u0080-\uFFFF]+/g);
  if (hashtagMatches) tags = hashtagMatches.map(h => h.replace(/^#/, '')).join(', ');

  results.push({ json: {
    video_id: postId, source_id: sourceInfo.source_id, source_name: sourceInfo.source_name,
    handle: sourceInfo.handle, title: caption.substring(0, 500), description: caption.substring(0, 500),
    tags, url, view_count: viewCount, like_count: likeCount, comment_count: commentCount,
    duration, published_at: publishedAt, channel_id: username, content_type: 'Reel', platform: 'Instagram'
  }});
}

if (!results.length) {
  console.log('[4] No ' + currentYear + '+ posts for: ' + source_name);
  return [{ json: { _skip_videos: true, source_id, source_name } }];
}

// Per-creator baseline median over last 30 videos (Framework Part 1.1).
// OS = views / channel median over last 30 videos.
// DEFENSIVE: node 5 runs downstream; guard the reference so a missing node 5 can't crash.
const historyByChannel = {};
let _existingRecs = [];
try {
  _existingRecs = $('5. Get All Existing Video IDs').all();
} catch (e) {
  console.log('[4] node 5 not executed yet, using current-run median');
}
for (const rec of _existingRecs) {
  const ch = (rec.json['Channel ID'] || '').toLowerCase().trim();
  if (!ch) continue;
  const v = parseInt(rec.json['View Count']) || 0;
  const ts = rec.json['Published At'] || '';
  if (!historyByChannel[ch]) historyByChannel[ch] = [];
  historyByChannel[ch].push({ v, ts });
}

function median(arr) {
  if (!arr.length) return 0;
  const s = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 === 0 ? (s[mid - 1] + s[mid]) / 2 : s[mid];
}

const currentByChannel = {};
for (const r of results) {
  const ch = r.json.channel_id;
  if (!currentByChannel[ch]) currentByChannel[ch] = [];
  currentByChannel[ch].push({ v: r.json.view_count, ts: r.json.published_at });
}

const baselineByChannel = {};
const allChannels = new Set([...Object.keys(historyByChannel), ...Object.keys(currentByChannel)]);
for (const ch of allChannels) {
  const combined = [...(historyByChannel[ch] || []), ...(currentByChannel[ch] || [])]
    .filter(x => x.v > 0)
    .sort((a, b) => String(b.ts).localeCompare(String(a.ts)))
    .slice(0, 30)
    .map(x => x.v);
  baselineByChannel[ch] = median(combined);
  console.log('[4] @' + ch + ': baseline median (last ' + combined.length + '): ' + baselineByChannel[ch]);
}

return results.map(r => {
  const baseline = baselineByChannel[r.json.channel_id] || 0;
  const outlierScore = baseline > 0 ? parseFloat((r.json.view_count / baseline).toFixed(2)) : 0;
  return { json: { ...r.json, outlier_score: outlierScore, baseline_median: baseline } };
});

// Gate 1 per AlfredAI Outlier & Relevance Scoring Framework: OS >= 2.0x
// Tiers: Mega-Viral (>5.0), Strong Outlier (2.0-5.0). Below 2.0 rejected.
const OUTLIER_THRESHOLD = 2.0;
const existingItems = $input.all();
const existingIds = new Set(existingItems.map(i => i.json['Video ID'] || '').filter(id => id !== ''));
const incomingItems = $('4. Extract & Score').all();

function tierFor(score) {
  if (score > 5.0) return 'Tier 1: Mega-Viral';
  if (score >= 2.0) return 'Tier 2: Strong Outlier';
  return null;
}

if (incomingItems.length === 1 && incomingItems[0].json._skip_videos) {
  const { source_id, source_name } = incomingItems[0].json;
  console.log('[6] No posts from Apify for: ' + source_name + ', marking backfilled anyway');
  return [{ json: { _skip: true, source_id, source_name } }];
}

const seenThisRun = new Set();
const outliers = [];
let skippedDupe = 0;
let skippedThreshold = 0;

for (const item of incomingItems) {
  if (item.json._skip_videos) continue;
  const vid = item.json.video_id;
  if (!vid || existingIds.has(vid) || seenThisRun.has(vid)) { skippedDupe++; continue; }
  seenThisRun.add(vid);
  const score = parseFloat(item.json.outlier_score) || 0;
  const tier = tierFor(score);
  if (tier) {
    outliers.push({ json: { ...item.json, is_outlier: true, outlier_tier: tier } });
  } else {
    skippedThreshold++;
  }
}

const source_id = incomingItems[0]?.json?.source_id || '';
const source_name = incomingItems[0]?.json?.source_name || '';

console.log('[6] Dupes: ' + skippedDupe + ' | Below 2.0x: ' + skippedThreshold + ' | Outliers: ' + outliers.length);

if (outliers.length === 0) {
  return [{ json: { _skip: true, source_id, source_name } }];
}

return outliers;

// Always pull source identity from 2a which is stable regardless of which path triggered us
let source_id = '';
let source_name = '';
try {
  const s = $('2a. Prepare Single Source Input').first().json;
  source_id = s.source_id || '';
  source_name = s.source_name || '';
} catch(e) {
  for (const item of $input.all()) {
    if (item.json.source_id) {
      source_id = item.json.source_id;
      source_name = item.json.source_name || '';
      break;
    }
  }
}
if (!source_id) {
  console.log('[10] No source_id found, skipping mark');
  return [];
}
const today = new Date().toISOString().split('T')[0];
console.log('[10] Preparing to mark backfilled: ' + source_name + ' (' + source_id + ')');
return [{ json: { source_id, source_name, last_scanned: today } }];

const items = $input.all();
if (!items.length) return [];

const source_id = items[0].json.source_id || '';
const source_name = items[0].json.source_name || '';

const toRecord = (v) => ({
  fields: {
    'Video ID': v.video_id,
    'Title': v.title,
    'URL': v.url,
    'Channel ID': v.channel_id,
    'Description': v.description,
    'Tags': v.tags,
    'Published At': v.published_at,
    'View Count': v.view_count,
    'Like Count': v.like_count,
    'Comment Count': v.comment_count,
    'Duration': v.duration,
    'Content Type': v.content_type,
    'Platform': v.platform,
    'Source Name': v.source_name,
    'Associated_Sources': v.source_id ? [v.source_id] : [],
    'Status': 'New',
    'Outlier Score': v.outlier_score || 0,
    'Outlier Tier': v.outlier_tier || '',
    'Creator_Handle': v.handle
  }
});

const chunks = [];
for (let i = 0; i < items.length; i += 10) {
  chunks.push(items.slice(i, i + 10).map(it => toRecord(it.json)));
}

console.log('[9a] ' + items.length + ' records -> ' + chunks.length + ' chunk(s) for: ' + source_name);
return chunks.map((records, idx) => ({
  json: { records, source_id, source_name, chunk: idx + 1, total_chunks: chunks.length }
}));

const source_id = $('9a. Chunk Records').first().json.source_id || '';
const source_name = $('9a. Chunk Records').first().json.source_name || '';
console.log('[9d] All chunks inserted for: ' + source_name);
return [{ json: { source_id, source_name } }];
